/**
 * @distilled.cloud/jira -- Jira Cloud platform REST API v3 SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-jira/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * The Jira platform API is one service, so its operations are exported
 * straight off the package root.
 *
 * @example
 * ```ts
 * import * as Jira from "@distilled.cloud/jira";
 *
 * const issue = yield* Jira.getIssue({ issueIdOrKey: "ACME-1" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { JiraProtocol, type JiraOpError, type JiraOpContext } from "./protocol.ts";
export { paginateStartAt, paginateToken } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/jira.ts";
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the operations raise the service-local classes.
export { BadRequest, Conflict, Forbidden, NotFound, UnprocessableEntity } from "./services/jira.ts";
